INSERT INTO `products` (`id`, `product_name`, `category`, `image`, `slug`, `description`, `features`, `created_at`) VALUES
(1,	'Hand Sealer Impulse Type',	7,	'1578659358.png',	'hand-sealer-300-sps-impulse-type',	'Hand sealing machine is ideal for sealing hand sealable poly pouches. It can be used for packing solid based, paste based and liquid based products. Ideal for use in shops, bakeries, packaging products. It is hand operated, impulse sealing. It gives a sealing length of 12\", 18\", 24\". It has a adjustable heat adjustor and audio and visual sealing indicators. It also comes with round element for sealing and cutting simultaneously. ',	'Hand sealing machine is ideal for sealing hand sealable poly pouches. It can be used for packing solid based, paste based and liquid based products. Ideal for use in shops, bakeries, packaging products. It is hand operated, impulse sealing. It gives a sealing length of 12\", 18\", 24\". It has a adjustable heat adjustor and audio and visual sealing indicators. It also comes with round element for sealing and cutting simultaneously. ',	'2019-07-13 10:10:10'),
(3,	'Hand Sealer 300 SPS Hot Bar Type',	7,	'1578659481.png',	'hand-sealer-sps-hot-bar-type',	'Hand sealing machine is ideal for sealing hand sealable poly pouches. It can be used for packing solid based, paste based and liquid based products. Ideal for use in shops, bakeries, packaging products. It is hand operated, impulse sealing. It gives a sealing length of 12\", 18\", 24\". It has a adjustable heat adjustor and audio and visual sealing indicators. It also comes with round element for sealing and cutting simultaneously. ',	'- Portable and compact size. \r\n- Low power consumption. \r\n- Perfect for sealing bags in household, supermarkets, kitchen or stores, such as cafe shop, candy store, snack booth, medicine shops, small factories etc.\r\n\r\nBuilt with Double Transformer for optimal ',	'2019-07-13 10:10:10'),
(4,	'Foot Sealer Impulse Type',	7,	'1578659545.png',	'foot-sealer-300sps-impulse-type',	'These Impulse sealing machine Makes excellent air and watertight seals on materials like P.P., L.D., H.M., H.D. and all similar heat sealable materials. These Pouch sealing Machines are manual and Easy to Operate. Simply place a bag between the sealing bars, press down and release. These Impulse Bag Sealing Machine are of metal construction and of industrial quality and built to last. ',	' - Most impulse sealing machinery are equipped with plug-in electronic timer and built in micro-switch. \r\n- No warm-up time is needed in these machines. \r\n- Power is used only when the sealing bar activates the micro-switch. \r\n- The variable timer let you seal',	'2019-07-13 10:10:10'),
(6,	'Foot Sealer 300 SPS Hot Bar Type',	7,	'1578659570.png',	'foot-sealer-300-sps-hot-bar-type',	'Additional features of HOT BAR SEALERS especially for sealing the multi layer laminated bags. Almost all the multi layer laminated bags of aluminium/ paper/ polyethylene/ polyurethane lamination can be sealed with the HOT BAR SEALERS. Lining Type Sealing Available In Hot Bar Sealers. ',	'Additional features of HOT BAR SEALERS especially for sealing the multi layer laminated bags. Almost all the multi layer laminated bags of aluminium/ paper/ polyethylene/ polyurethane lamination can be sealed with the HOT BAR SEALERS. Lining Type Sealing Available In Hot Bar Sealers. ',	'2019-07-13 10:10:10'),
(7,	'Pneumatic Sealer 750 SPS Impulse Type',	7,	'1563029531.jpg',	'pneumatic-sealer-750-sps-impulse-type',	'Pneumatic Impulse Sealer Machine having ability to handle large quantities of load. The Pneumatic Impulse Sealer Machine is popular in the industry, owing to its wide applicability, user-friendliness and proven features. We manufacture Pneumatic Impulse Sealer Machine from the finest grade raw material, using contemporary techniques. The product meets significant standards of quality. This range can be modified as per client-specific demands. ',	' â€¢	Safety fuse for power surge/fluction.\r\n\r\nâ€¢	2 timer controls V 1 for the duration of pressure,1 for the heat increment\r\n\r\nâ€¢	Just feed in the packs in m/c bands they get Quickly sealed ',	'2019-07-13 10:10:10'),
(8,	'Movable Sealer 750SPS Impulse Type',	7,	'1563029554.jpg',	'movable-sealer-750sps-impulse-type',	'An envelope sealing apparatus for sealing an envelope having a main body and a sealable flap foldable about a hinge between the flap and main body, and sealable thereto. The apparatus comprises a feed path along which an envelope can be fed; a driving means associated with the feed path for feeding an envelope along the feed path; a flap securing means cooperative with the driving means to secure an open envelope flap in contact with the driving means; and a flap sealing means cooperative with the driving means to seal the flap to the main body when the driving means drives the envelope in a flap sealing direction along the feed path. A mail piece creation device incorporating such an envelope sealer is further provided, along with corresponding methods. ',	' ',	'2019-07-13 10:10:10'),
(9,	'Bread Sealer Machine',	7,	'1563029574.jpg',	'bread-sealer-machine',	'Bread sealer is perfect for sealing your bakery items. After Placing your baked god into a plastic bag, simply run your entire bag through the machine to keep your product fresh and safe with a tamper-evident closur \r\n',	' - Tamper evident bag closure. \r\n\r\n- Reseal able . \r\n\r\n- Easy to use.\r\n\r\n- Food Safety.\r\n\r\n- Economic.\r\n',	'2019-07-13 10:10:10'),
(10,	'I-Bar Sealer',	7,	'1563029596.jpg',	'i-bar-sealer',	'A complete shrink wrap system or kit to professionally package any product. All systems consist of a roll of film or shrink bags to wrap the package, a sealer with round wire to seal and cut the film and a heat gun to shrink the film. Easy operation:Insert item in the shrink bag or between the folds of film. Seal and cut film by lowering the sealing bar. Apply hot air using heat gun to shrink the film tightly around the package ',	' ',	'2019-07-13 10:10:10'),
(11,	'Semi Automatic Cup Sealing Machine',	13,	'1576490998.png',	'semi-automatic-cup-sealing-machine',	'We offer wide range of Semi Automatic Cup sealing Machine .This sealing machine manufactured by using best quality material and modern technology ,it is also easy to operate and sealing capacity is 300-400 cup/hour ',	' ',	'2019-07-13 10:10:10'),
(12,	'Horizontal Sealer 900LW',	8,	'1578659633.png',	'horizontal-sealer-900lw',	'Horizontal band sealers are used to perform band sealing operations in the horizontal pose. It is efficient packaging equipment that is cost effective and known for its high performance. The sealer has a PVC conveyor belt of width 200 millimetres that is capable of carrying weight of up to 3 kilograms. It is produced by using high grade steel and castings along with epoxy powder coated body. ',	' ',	'2019-07-13 10:10:10'),
(13,	'Vertical Sealer 750LW',	8,	'1578659897.png',	'vertical-sealer-750lw',	'If you need to vertically seal thermoplastic bags on a low to medium-volume level. This vertical sealer features a stainless steel design along with an easy-to-use control panel found on the top right side of the machine. Bags are fed from the right and pulled through the sealer, producing an 8mm wide seal along the open end of the thermoplastic bag. ',	' ',	'2019-07-13 10:10:10'),
(14,	'Vertical Sealer with Nitrogen Flush',	8,	'1563029948.jpg',	'vertical-sealer-with-nitrogen-flush',	'If you need to vertically seal thermoplastic bags on a low to medium-volume level. This vertical sealer features a stainless steel design along with an easy-to-use control panel found on the top right side of the machine. Bags are fed from the right and pulled through the sealer, producing an 8mm wide seal along the open end of the thermoplastic bag. ',	' ',	'2019-07-13 10:10:10'),
(15,	'Vertical Sealer (10kg)',	8,	'1563029981.jpg',	'vertical-sealer-10kg',	'This machine is used for sealing various pre-made pouches and it is a best sealing equipment to be widely used in food ',	' ',	'2019-07-13 10:10:10'),
(16,	'Double Side Band Sealer',	8,	'1563030010.jpg',	'double-side-band-sealer',	'If you need to vertically seal thermoplastic bags on a low to medium-volume level. This vertical sealer features a stainless steel design along with an easy-to-use control panel found on the top right side of the machine. Bags are fed from the right and pulled through the sealer, producing an 8mm wide seal along the open end of the thermoplastic bag. ',	' ',	'2019-07-13 10:10:10'),
(17,	'Band sealing up to 5 kg',	8,	'1578659698.png',	'band-sealing-up-to-5-kg',	'This machine is used for sealing various pre-made pouches and it is a\r\nbest sealing equipment to be widely used in food ',	' ',	'2019-07-13 10:10:10'),
(18,	'Heavy duty band sealer up to 20 kg',	8,	'1563030073.jpg',	'heavy-duty-band-sealer-up-to-20-kg',	'This machine is used for sealing various pre-made pouches and it is a\r\nbest sealing equipment to be widely used in food ',	' ',	'2019-07-13 10:10:10'),
(19,	'Single Thread DADR',	9,	'1563030122.jpg',	'single-thread-dadr',	'DA is a single-thread chain-stitch portable filled bags closing sewing machine. This robust machine stands up to the most demanding sewing jobs on all types of paper, textile and poly bags made from HDPE/PP, etc. It is simple to operate, even for inexperienced users. The reinforced feed mechanism consisting of wider presser foot and feed dog with a bigger throat plate than conventional single thread chain-stitch bag closing machines helps achieve smoother, even and better looking plain and folded top closures.',	' ',	'2019-07-13 10:10:10'),
(20,	'Double Thread DADR',	9,	'1563030295.jpg',	'double-thread-dadr',	'The DAD is a twin needle, double-thread, parallel chain-stitch, portable bag closing sewing machine. Its strong construction and design offers long-life reliable performance requiring minimum maintenance. This robust machine stands up to the most demanding sewing jobs on all types of paper, textile and poly bags made from HDPE/PP, etc. It is simple to operate, even for inexperienced users. The reinforced feed mechanism consisting of wider presser foot and feed dog with a bigger throat plate than conventional double thread chain-stitch bag closing machines helps achieve smoother, even and better looking plain and folded top closures. ',	' ',	'2019-07-13 10:10:10'),
(21,	'Manual Strapping Tool for PP Strip',	10,	'1576489793.jpg',	'manual-strapping-tool-for-pp-strip',	'Strapping Manual hand tensioners allow operators to bring strap to desired tension with minimal interruption, effort and strap waste. Strapping Manual sealers provide positive sealing action with minimal effort. Light and durable, they lock strap ends into a high strength joint. ',	' ',	'2019-07-13 10:10:10'),
(22,	'Manual Strapping Tool for PET Strip',	10,	'1576489862.jpg',	'manual-strapping-tool-for-pet-strip',	'High Tensile Manual Hand Sealer are the most basic form of strap application equipment. They are perfect for operations that either do not have access to power sources or do not require the speed of powered hand tools. ',	' - By reducing packaging cost - By improving the arrival condition of their products - By making their operations more productive.',	'2019-07-13 10:10:10'),
(23,	'Manual Strapping Tool for MS Strip',	10,	'1576489917.jpg',	'manual-strapping-tool-for-ms-strip',	'Manual Steel Strapping Tensioner is offered by us are an ideal alternative for heavy duty steel strapping applications with push or cover types seal/clips. In addition to this, the offered range is known for its excellent performance, resistance to breakage and compact design. ',	' - Manual Steel Strap tensioner - MIP heavy duty steel strap tensioner - Flat surface load - Round or irregular surface load.',	'2019-07-13 10:10:10'),
(24,	'Pneumatic Strapping Tool for PET Strip ADQ19',	10,	'1576490013.png',	'pneumatic-strapping-tool-for-pet-strip-adq19',	'The Pneumatic Strapping Machine which we offer finds great application in Packaging Industry. These Pneumatic Strapping Machines are designed for neutral packaging. Widely used in companies which exports iron, textile, household, electrical appliance, stone material and chemical fibre, the Pneumatic Strapping Machine finishes the soldering of PET tape at high speed. Known for high performance, precisely engineered design, high strapping efficiency, and long service life, the Pneumatic Strapping Machine is widely demanded by the clients. ',	' - Strains, sticks ',	'2019-07-13 10:10:10'),
(25,	'Semi Automatic Strapping Machine SPS 405',	10,	'1576490168.jpg',	'semi-automatic-strapping-machine-sps-405',	'Semiautomatic strapping machine is suitable for cartons, calcium-plastic cases, books, soft and hard packages as well as all kinds of articles in square, cylinder or annulations. The machine with high table is suitable for general objects, while that with table in middle height is suitable for those packages that are larger or heavier. Strapping machine with very low table is suitable for the packages that are very large or heavy.',	' - Instant Heating in only 20 second. - Magnetic drive for faster speed packing. - Lift type top cover allows convenient maintenance. - Safety switch activate as soon as open the top cover. ',	'2019-07-13 10:10:10'),
(26,	'Semi Automatic Strapping Machine SPS 306',	10,	'1576490290.jpg',	'semi-automatic-strapping-machine-sps-306',	'A semiautomatic strapping machine is suitable for cartons, calcium-plastic cases, books, soft and hard packages as well as all kinds of articles in square, cylinder or annulations. The machine with high table is suitable for general objects, while that with table in middle height is suitable for those packages that are larger or heavier. Strapping machine with very low table is suitable for the packages that are very large or heavy. ',	' ',	'2019-07-13 10:10:10'),
(27,	'Semi Automatic Strapping Machine SPS 207',	10,	'1576490380.jpg',	'semi-automatic-strapping-machine-sps-207',	'Semiautomatic strapping machine is suitable for cartons, calcium-plastic cases, books, soft and hard packages as well as all kinds of articles in square, cylinder or annulations. The machine with high table is suitable for general objects, while that with table in middle height is suitable for those packages that are larger or heavier. Strapping machine with very low table is suitable for the packages that are very large or heavy. ',	' - Instant Heating in only 20 second. - Magnetic drive for faster speed packing. - Lift type top cover allows convenient maintenance. - Safety switch activate as soon as open the top cover. - Economical design of control switch, independent PCB control fire.',	'2019-07-13 10:10:10'),
(28,	'Low Table Top Semi Automatic Strapping Machine SP 101L',	10,	'1576490471.jpg',	'low-table-top-semi-automatic-strapping-machine-sp-101l',	'Low Table Top Strapping Machine is suitable for cartons, calcium-plastic cases, books, soft and hard packages as well as all kinds of articles in square, cylinder or annulations. The machine with very low table is suitable for the packages that are very large or heavy. ',	' - Useful for easy transportation ',	'2019-07-13 10:10:10'),
(29,	'Fully Automatic Strapping Machine',	10,	'1576490564.jpg',	'fully-automatic-strapping-machine',	'The Fully automatic strapping machines provided by us are developed with state-of-the-art innovative designs. These are compact and assembled for lightweight to ensure easy mobility. This machine is fitted with a concise, low maintenance sealer head. ',	' - Energy saving mode that activates within 2 min of non-use and allows for instant operation. - 20 seconds warm up period and quiet intermittent action control. - Excellent quality of timer, solenoid and other electrical components. ',	'2019-07-13 10:10:10'),
(30,	'PET Strapping Tool Battery Powered ',	10,	'1576490658.jpg',	'pet-strapping-tool-battery-powered',	'Battery Operated Pet Strapping Tool  is used to Strapping  objects like Cartons ,boxes, pallets ',	'1) Light  Weight\r\n2) Easy  To Carry\r\n3) Low Maintenance\r\n4) High Tensile\r\n5) Easy Operation',	'2019-07-13 10:10:10'),
(31,	'Heat Gun SPS 750',	11,	'1576488470.jpg',	'heat-gun-sps-750',	'Heat Gun tools are used for loosening of jammed bearings, nuts, bolts, mechanical spare parts. In addition, our Heat Gun is used for the removal of paint, wall papers, varnish and putty from various metal surfaces. We design these guns at our state of the art machining facility using best quality materials and sophisticated technology. ',	' - Ergonomically shaped handle for smooth handling - Light weight with industrial grade rubber power cord - Two heat settings for all hot-air applications without reduction nozzles',	'2019-07-13 10:10:10'),
(32,	'Shrink Tunnel SPS 2012',	11,	'1576488639.png',	'shrink-tunnel-sps-2012',	'Shrink tunnel Model SPS2012 adopts hot-wind and down-cyclone structure, intelligence temperature control, and variable speed regulation. There are two optional conveyors, including Teflon belt type and roller type. Shrink tunnel are applied to heat shrinkable film such as PVC, POF, PP etc. ',	' - Deliver fast and smooth operation - Has a robust body - Low power consumption - Provided with digital/deviation thermostatic heat controlling system - User friendly - Variable and fix conveyor speed',	'2019-07-13 10:10:10'),
(33,	'Shrink Tunnel SPS4525',	11,	'1576488955.png',	'shrink-tunnel-sps4525',	'Shrink tunnel Model SPS4525 adopts hot-wind ',	' - Deliver fast and smooth operation - Has a robust body - Low power consumption - Provided with digital/deviation thermostatic heat controlling system - User friendly - Variable and fix conveyor speed',	'2019-07-13 10:10:10'),
(34,	'L-Sealer with Tunnel SPS 4525',	11,	'1576489090.jpg',	'l-sealer-with-tunnel-sps-4525',	'The L-Sealer ',	' - The L-Sealers benefit from an adjustable height, powered out feed conveyor belt - The shrink tunnel has lockable wheels - The L-Sealers have adjustable height feet - The shrink tunnel has a silicone coated roller conveyor\r\n',	'2019-07-13 10:10:10'),
(35,	'L-Sealer Conveyor SPS 5045',	11,	'1576489179.jpg',	'l-sealer-conveyor-sps-5045',	'L-Sealer with Conveyor cutting machine can convey the products automatically into shrink tunnel through conveying belt for shrink packaging after sealing ',	' - There is protection mechanism for sealing knife against overheating and cutting. - Adopt nano-fiber cutter holder and anti sticking thermos table nichrome cutter for sealing ',	'2019-07-13 10:10:10'),
(36,	'L-Sealer Manual SPS 300',	11,	'1576489324.jpg',	'l-sealer-manual-sps-300',	'L-Sealer Manual Machines are used for packaging sweets, medicines, confectioneries, stationeries and garments. Our L-Sealer Manual Machine is made at our ultramodern manufacturing facility by using the best quality materials and sophisticated technology. Our clients can avail these machines from us at nominal prices. ',	' - Height adjustments for different heights of the products and adjustable production loading tray - Products of different sizes and shapes are easily over wrapped for perfect presentation',	'2019-07-13 10:10:10'),
(37,	'Chamber Type Shrink Machine SPS 1520',	11,	'1576489415.jpg',	'chamber-type-shrink-machine-sps-1520',	'Shrink Chamber machine combines sealing with shrinking into one step. It suitable for all kinds of shrink films such as PVC, POF, PP etc. And the transparent cover makes the process of sealing ',	' - Combined function of sealing and shrinking. - Low electrical consumption. - Suitable for wrapping single or multipacks. - Portable model with less space requirement',	'2019-07-13 10:10:10'),
