INSERT INTO `seo` (`id`, `title`, `slug`, `keywords`, `description`) VALUES
(1,	'Home',	'/',	'Smartpack, best sealing machines,best handling machines		',	'Founded in Dec 1998 in Indore, INDIA, SmartPack is India\'s first and the largest fully managed marketplace that offers a safe and trusted online platform for Packaging Machine & Packaging Material.				'),
(2,	'About us',	'/about-us',	'Smart pack, about us, Packaging Machine Seller, Coding Machine Supplier, Trader',	'Smart Packaging Systems is one of the Leading packaging and coding machine supplier in India, We have all range of packaging machines is available, smart pack specialized in the customized packaging machine.'),
(4,	'Contact Us',	'/contact',	'smart pack india, contact us',	'This is smart pack india contact us page'),
(29,	'Pouch Sealing Machine India | Industrial Sealing Machine Supplier',	'/items/sealing-machine',	'Hand Operated Packing Machine, Foot Operated Sealing Machine , Bread Sealing Machine, Packaging Machines, Small Packing Machine.',	'We are supplier, manufacturer & distributors of all type of sealing machines in all the state of India, We have manual, Semi-automatic and automatic Machines.'),
(30,	'Packaging Machines Company India - Mumbai, Banglore, Bhubneswar, Jaipur',	'/category/packaging-machine',	'packaging supplies,  cookies packaging manufacturer,Plastic packet packing, Low cost Packing Machine.',	'Smart Packaging Systems is the Supplier of Packaging Machines, we also provide customized machine used in various industries. '),
(31,	'Manual Pouch Packing Machine | Hand Sealing Machine India  | smartpackindia.biz',	'/product/hand-sealer-300-sps-impulse-type',	'Plastic bag sealer with the cutter, Portable Heat Seal Food Packaging machine, Impulse heat sealer, 12-inch hand sealing Machine, sealing machine suppliers India',	'Best quality industrial Handheld heat sealer machine use for sealing Plastic Pouch like vaccum, silver, aluminum bags. It can seal and cut the pouch in a single step.'),
(32,	'Impulse Heat Sealing Machine India | Plastic Bags Packaging Machine',	'/product/hand-sealer-500-sps-impulse-type',	'Impulse heat sealer, sealing packaging machine, pouch sealing machine, Portable Pouch Packing Machine, Smartpack India, sealing machine manufacturer India',	'Low-cost hand sealing machine used for Sealing Plastic Pouch with different sealing length. We serve in Jaipur, Hyderabad, Chennai, Kolkata, Pune, Bhubaneshwar.'),
(33,	'Heavy Duty Hand Sealing Machine | Hand Sealer Hot Bar Type Machine',	'/product/hand-sealer-sps-hot-bar-type',	'Hot Bar Heat Sealing Machine, Portable Pouch Packaging Machine, Multilayer laminated bags sealing Machine, hot bar hand sealer machine India',	'Manual heat sealing machine with the sealing width 12mm uses for sealing all type of multilayer laminated pouch. We serve in Hyderabad, Jaipur, Kolkata, Bhubaneshwar.'),
(34,	'Impulse sealing machine | Foot operated heat sealer machine India',	'/product/foot-sealer-300sps-impulse-type',	'pedal Impulse sealing machine, pouch sealing machine, foot operated poly bag sealer, Double transformer sealing machine, impulse sealing machine india',	'Contact us for packaging machine like Foot Sealer with the different sealing Length and Width as per customer need. Its used to Seal PP, HDPE, LD, Laminated & Paper bags.'),
(35,	'Foot operated poly bag sealer | Plastic Pouch Packaging Machine India',	'/product/foot-sealer-500-sps-impulse-type',	'Padal Sealing Machine, Pouch Packaging Machine, Sealing Machine in India, Food Packing Machine Distributor India, Food Packing Machine Manufacturer India',	'We are the leading supplier of efficient packaging machine like impulse type Pedal Operated Sealing Machine with the different sealing Length and Width as per customer need.'),
(36,	'Foot Sealing Machine | Padal Sealing Machine Supplier India',	'/product/foot-sealer-300-sps-hot-bar-type',	'Foot Operated Pouch Packing Machine in India, Multilayer laminated Pouch Sealing machine supplier in India, Foot Sealing Machine in India',	'Smart Packaging Systems offers Hot Bar Type Foot Sealing Machine for packing all type of Multilayer Laminated pouch of aluminum/paper/polyethylene/polyurethane.'),
(37,	'Pneumatic sealing machine India | Pouch packing machine - Kolkata',	'/product/pneumatic-sealer-750-sps-impulse-type',	'Pneumatic Heat Sealing Machine, Pneumatic Impulse Sealer Machine, 25kg Pouch Packaging Machine, 50 kg Plastic Bag Sealing Machine, Pouch packing machine in India',	'Pneumatic Impulse Sealer Machine is suitable For Packing aluminium bag, Paper Bags, Vacuum Pouches & 25 kg -50kg plastic bags, it\'s used for Namkeen, Snacks, Confectionery items Packings.'),
(38,	'Plastic bag sealers supplier | Impulse Type Movable Sealing Machine',	'/product/movable-sealer-750sps-impulse-type',	'plastic bag stitching machine, bag stitching machine India, Heavy Plastic Pouch Sealing Machine, Movable Sealing Machine manufacturer in India',	'Mobile sealing machine widely used for sealing Heavy Plastic Bags ideal for tea sacks, spices & chemical packing. It\'s used in pharma, food & export industries.'),
(39,	'Bread Bag Sealing Machine India | Bakery Packaging Machine',	'/product/bread-sealer-machine',	'bread bag sealer, bread sealing machine, bakery items packaging machine, bread bag sealing machine, bread wrapping machine india',	'Bread Sealer is perfect for sealing your bakery items. We serve in Jaipur, Kolkata, Hyderabad, Bhubaneshwar, Pune, Chennai & rest of India.'),
(40,	'Mini shrink wrap machine | i-bar sealer | Portable shrink sealer',	'/product/i-bar-sealer',	'Portable shrink sealer, portable shrink wrap machine, mini shrink wrap machine India, I bar sealing machine in India',	'I-bar sealing machine is a complete shrink wrap system with shrink roll film or bag to cover the package. We serve in Jaipur, Kolkata, Hyderabad, Bhubaneshwar, Chennai, Pune.'),
(41,	'Poly Sealing Machine | Horizontal Band Sealing Machine in india',	'/items/band-sealing-machine',	'agarbatti pouch sealer, Packaging Machine in India, Sugar Bag Packing Machine, Pouch Sealing Machine, band sealing machine in India',	'This machine is used for sealing Plastic Bags in FMCG, Pesticide, Electronic Parts manufacturing Industries. We also serve in all the states of India.'),
(42,	'Horizontal Band Sealer | Plastic Bags Sealing Machine India',	'/product/horizontal-sealer-900lw',	'namkeen packing machine, continuous Plastic bag sealing machine, Spices Pouch Packing Machine, Horizontal band sealing machine in India',	'This machine used for sealing filled pouch like center seal Plastic Bag, three Side Seal, Stand up and Zipper Pouch which is Made from Laminated Film.'),
(43,	'Vertical continuous band sealer | Automatic bag sealing machine',	'/product/vertical-sealer-750lw',	'hot plastic sealer, Platic Laminated Pouch Packaging Machine, Stand up Pouch Sealing Machine supplier India, Masala Pouch Packing machine in India',	'Smart Pack -  Supplier and exporter of all type of Band Sealing Machines. We offer different range Of Pouch Packaging Machines, all use to Seal Plastic Bags.'),
